func:
// Captura o objeto vindo do nó S7 in (modo 'all')
const dados = msg.payload;

// Converte o tempo de amortização de milissegundos para segundos (Time no CLP vem em ms)
const tempoAmortizacaoSegundos = dados["TEMPO_AMORTIZAÇÃO"]
    ? Number(dados["TEMPO_AMORTIZAÇÃO"]) / 1000.0
    : 0.0;

// Estruturação no formato de gravação do InfluxDB v2 [Fields, Tags]
msg.payload = [
    {
        // Medições físicas escalonadas
        nivel: Number(dados.Nivel || 0.0),
        temperatura: Number(dados.Temperatura || 0.0),
        pressao_pn2594: Number(dados.PN2594_PRESSAO || 0.0),
        velocidade_real: Number(dados.VELOCIDADE_BOMBA || 0.0),
        setpoint_nivel: Number(dados.SP || 0.0),
        velocidade_comandada: Number(dados.SPEED_SP || 0.0),
        tempo_estabilizacao: Number(tempoAmortizacaoSegundos)
    },
    {
        // Tags para filtragem no InfluxDB e no Python
        tipo_ensaio: "perturbacao_extrema", // Identifica a batelada baseline
        equipamento: "automazoom"
    }
];

return msg;
